class PyplotSim:
    """Tiny model of pyplot: commands hit the CURRENT (last-made) axes."""
    def __init__(self):
        self.axes = []
    def subplots(self, count):
        self.axes = ['ax%d' % i for i in range(count)]
        return list(self.axes)
    def _current(self):
        return self.axes[-1]
    def plot(self, x, y):
        return self._current() + '.plot(%s, %s)' % (x, y)
    def title(self, text):
        return self._current() + '.set_title(%r)' % text

plt = PyplotSim()
made = plt.subplots(2)
print('created:', made)
print("plt.plot('x', 'y')    runs on ->", plt.plot('x', 'y'))
print("plt.title('mine')     runs on ->", plt.title('mine'))
